#!/bin/sh
# ── Stalwart v0.16 activation hook ─────────────────────────────────────
# Runs after compose-up. Idempotent.
#
# Per user in build.json#users:
#   1. Wait for admin API.
#   2. Discover JMAP accountId from /jmap/session.
#   3. Create mailbox hierarchy (4 parents + 10 leaves) declared in
#      mail-rules-general.json::folders + folders_ui. Skips existing.
#   4. Upload + activate dist/configs/default.sieve via JMAP Sieve API.
#
# Plus (admin scope):
#   D. Apply outbound MTA routes declared in build.json#mta_routes,
#      emitted as configs/mta-routes.json by the flake. Secrets pulled
#      from $SECRETS_DIR/<env-var-name>. No hardcoded data in this file.
#
# Domain + Account creation are owned by stalwart-cli apply (manual
# recovery-mode bootstrap), NOT this hook.
#
# Folder list and user/pass-env pairs are injected by the flake from
# mail-rules-general.json + build.json#users. They appear below inside
# single-quoted strings; NEVER reference the @VAR@ tokens in comments
# (engine substitutes everywhere — multi-line values break shell parsing).
set -e
BASE="https://10.0.0.3:2443"
SECRETS_DIR="/opt/containers/stalwart/.secrets.d"
CONFIGS_DIR="/opt/containers/stalwart/configs"
SIEVE_FILE="$CONFIGS_DIR/default.sieve"
MTA_ROUTES_FILE="$CONFIGS_DIR/mta-routes.json"

PW=$(cat "$SECRETS_DIR/ADMIN_PASSWORD" 2>/dev/null || echo)
[ -z "$PW" ] && echo "[activate] No ADMIN_PASSWORD found, skipping" && exit 0

echo "[activate] Waiting for Stalwart admin API on $BASE ..."
_ready=0
for i in $(seq 1 60); do
  _code=$(curl -sk -o /dev/null -w '%{http_code}' -u "admin:$PW" "$BASE/jmap/session" 2>/dev/null || echo 000)
  case "$_code" in
    2*|4*) _ready=1; break ;;
  esac
  sleep 2
done
if [ "$_ready" != 1 ]; then
  echo "[activate] ERROR: Stalwart admin API never became ready (last HTTP $_code)" >&2
  exit 1
fi

# Resolve a mailbox id by name from current Mailbox/get response (JSON in $1).
# Outputs the id (no quotes) or empty string.
mailbox_id_for() {
  printf '%s' "$1" | python3 -c "
import sys, json, re
data = sys.stdin.read()
name = '''$2'''
# Find the most-recent Mailbox/get 'list' array.
m = re.search(r'\"list\":\\s*(\\[.*?\\])\\s*,\\s*\"notFound\"', data, re.DOTALL)
if not m:
    sys.exit()
try:
    for box in json.loads(m.group(1)):
        if box.get('name') == name:
            print(box['id'])
            break
except Exception:
    pass
"
}

# ── Per-user setup ────────────────────────────────────────────────────
for PAIR in me=ME_PASSWORD no-reply=NOREPLY_PASSWORD; do
  U=${PAIR%%=*}
  PASS_ENV=${PAIR#*=}
  USER="$U@diegonmarcos.com"
  USER_PW=$(cat "$SECRETS_DIR/$PASS_ENV" 2>/dev/null || echo)
  if [ -z "$USER_PW" ]; then
    echo "[activate]   $USER: no password ($PASS_ENV), skipping"
    continue
  fi

  echo "[activate] Setup $USER..."

  SESSION=$(curl -sk -u "$USER:$USER_PW" "$BASE/jmap/session" 2>/dev/null)
  ACCOUNT_ID=$(printf '%s' "$SESSION" | grep -o '"urn:ietf:params:jmap:mail":"[^"]*"' | head -1 | cut -d'"' -f4)
  if [ -z "$ACCOUNT_ID" ]; then
    echo "[activate]   $USER: could not discover accountId, skipping"
    continue
  fi

  # ── Step B: create missing mailboxes ─────────────────────────────
  refresh_existing() {
    EXISTING=$(curl -sk -u "$USER:$USER_PW" -X POST "$BASE/jmap/" \
      -H "Content-Type: application/json" \
      -d "{\"using\":[\"urn:ietf:params:jmap:core\",\"urn:ietf:params:jmap:mail\"],\"methodCalls\":[[\"Mailbox/get\",{\"accountId\":\"$ACCOUNT_ID\",\"ids\":null,\"properties\":[\"id\",\"name\",\"parentId\"]},\"0\"]]}" 2>/dev/null)
  }
  refresh_existing

  printf '%s\n' '10 _ ADMIN|
20 _ INFORMS|
30 _ DEV|
AA _ OTHERS|
11    🛡️ Admin & Finance|10 _ ADMIN
Ab    📥 Archive|AA _ OTHERS
21    💼 Career & Network|20 _ INFORMS
13    ☁️ Cloud - General & Reports|10 _ ADMIN
14    ☁️ Cloud - Workflows|10 _ ADMIN
31    🎓 Development & Tech|30 _ DEV
23    🧻 Goverment|20 _ INFORMS
Ac    🚫 Junk|AA _ OTHERS
12    ✈️ Logistics|10 _ ADMIN
Aa    📬 Others (fallback)|AA _ OTHERS
22    📰 Social & General|20 _ INFORMS' | while IFS='|' read -r FNAME FPARENT; do
    [ -z "$FNAME" ] && continue

    # Skip if already exists.
    EXISTING_ID=$(mailbox_id_for "$EXISTING" "$FNAME")
    if [ -n "$EXISTING_ID" ]; then
      continue
    fi

    # Resolve parentId (null for top-level, otherwise lookup parent's id).
    PARENT_JSON="null"
    if [ -n "$FPARENT" ]; then
      PARENT_ID=$(mailbox_id_for "$EXISTING" "$FPARENT")
      if [ -z "$PARENT_ID" ]; then
        echo "[activate]   skip '$FNAME' — parent '$FPARENT' not yet created"
        continue
      fi
      PARENT_JSON="\"$PARENT_ID\""
    fi

    RESP=$(curl -sk -u "$USER:$USER_PW" -X POST "$BASE/jmap/" \
      -H "Content-Type: application/json" \
      -d "{\"using\":[\"urn:ietf:params:jmap:core\",\"urn:ietf:params:jmap:mail\"],\"methodCalls\":[[\"Mailbox/set\",{\"accountId\":\"$ACCOUNT_ID\",\"create\":{\"new\":{\"name\":\"$FNAME\",\"parentId\":$PARENT_JSON}}},\"0\"]]}" 2>/dev/null)

    if printf '%s' "$RESP" | grep -q '"created":{[^}]*"id"'; then
      echo "[activate]   created mailbox '$FNAME'"
      refresh_existing
    else
      echo "[activate]   FAIL create '$FNAME': $(printf '%s' "$RESP" | head -c 200)"
    fi
  done

  # ── Step C: upload + activate sieve script ─────────────────────────
  if [ ! -f "$SIEVE_FILE" ]; then
    echo "[activate]   no $SIEVE_FILE, sieve skipped"
    continue
  fi

  SIEVE_ACCT=$(printf '%s' "$SESSION" | grep -o '"urn:ietf:params:jmap:sieve":"[^"]*"' | head -1 | cut -d'"' -f4)
  [ -z "$SIEVE_ACCT" ] && SIEVE_ACCT="$ACCOUNT_ID"

  UPLOAD_RESP=$(curl -sk -u "$USER:$USER_PW" -X POST "$BASE/jmap/upload/$SIEVE_ACCT/" \
    -H "Content-Type: application/sieve" --data-binary @"$SIEVE_FILE" 2>/dev/null)
  BLOB_ID=$(printf '%s' "$UPLOAD_RESP" | grep -o '"blobId":"[^"]*"' | head -1 | cut -d'"' -f4)
  if [ -z "$BLOB_ID" ]; then
    echo "[activate]   sieve blob upload failed: $UPLOAD_RESP"
    continue
  fi

  JMAP_RESP=$(curl -sk -u "$USER:$USER_PW" -X POST "$BASE/jmap/" \
    -H "Content-Type: application/json" \
    -d "{\"using\":[\"urn:ietf:params:jmap:core\",\"urn:ietf:params:jmap:sieve\"],\"methodCalls\":[[\"SieveScript/set\",{\"accountId\":\"$SIEVE_ACCT\",\"create\":{\"default\":{\"name\":\"default\",\"blobId\":\"$BLOB_ID\"}},\"onSuccessActivateScript\":\"#default\"},\"0\"]]}" 2>/dev/null)

  if printf '%s' "$JMAP_RESP" | grep -q '"created":{[^}]*"id"'; then
    echo "[activate]   sieve created + activated for $USER"
  else
    LIST=$(curl -sk -u "$USER:$USER_PW" -X POST "$BASE/jmap/" \
      -H "Content-Type: application/json" \
      -d "{\"using\":[\"urn:ietf:params:jmap:core\",\"urn:ietf:params:jmap:sieve\"],\"methodCalls\":[[\"SieveScript/get\",{\"accountId\":\"$SIEVE_ACCT\"},\"0\"]]}" 2>/dev/null)
    SID=$(printf '%s' "$LIST" | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4)
    if [ -n "$SID" ]; then
      curl -sk -u "$USER:$USER_PW" -X POST "$BASE/jmap/" \
        -H "Content-Type: application/json" \
        -d "{\"using\":[\"urn:ietf:params:jmap:core\",\"urn:ietf:params:jmap:sieve\"],\"methodCalls\":[[\"SieveScript/set\",{\"accountId\":\"$SIEVE_ACCT\",\"update\":{\"$SID\":{\"blobId\":\"$BLOB_ID\"}},\"onSuccessActivateScript\":\"$SID\"},\"0\"]]}" >/dev/null 2>&1
      echo "[activate]   sieve updated + activated for $USER"
    else
      echo "[activate]   sieve create+update both failed: $JMAP_RESP"
    fi
  fi
done

# ── Step D: outbound MTA routes (admin scope) ──────────────────────────
# Driven entirely by configs/mta-routes.json + $SECRETS_DIR. Idempotent:
# routes are matched by `name`; existing → update, new → create. Routes
# flagged `default_outbound:true` are wired into the (singleton)
# MtaOutboundStrategy.route expression so all non-local mail is relayed
# through them. Empty file or empty array = no-op.
if [ -s "$MTA_ROUTES_FILE" ] && [ "$(cat "$MTA_ROUTES_FILE")" != "[]" ]; then
  echo "[activate] Applying MTA routes from $MTA_ROUTES_FILE ..."
  python3 - "$MTA_ROUTES_FILE" "$BASE" "admin:$PW" "$SECRETS_DIR" <<'PYEOF'
import sys, json, ssl, os, base64
from urllib import request as ur, error as ue

routes_path, base, auth, secrets_dir = sys.argv[1:5]
with open(routes_path) as f:
    routes = json.load(f)

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

def jmap(calls):
    body = json.dumps({
        "using": ["urn:ietf:params:jmap:core", "urn:stalwart:jmap"],
        "methodCalls": calls,
    }).encode()
    req = ur.Request(base + "/jmap/", data=body, method="POST",
        headers={
            "Content-Type": "application/json",
            "Authorization": "Basic " + base64.b64encode(auth.encode()).decode(),
        })
    try:
        return json.loads(ur.urlopen(req, context=ctx, timeout=15).read())
    except ue.HTTPError as e:
        return {"error": e.code, "body": e.read().decode(errors='replace')[:400]}

def read_secret(var):
    if not var: return None
    p = os.path.join(secrets_dir, var)
    try:
        with open(p) as f: return f.read().strip()
    except FileNotFoundError:
        print("  [warn] missing secret file:", p)
        return None

def discover_admin_account():
    body = ur.Request(base + "/jmap/session", method="GET",
        headers={"Authorization": "Basic " + base64.b64encode(auth.encode()).decode()})
    s = json.loads(ur.urlopen(body, context=ctx, timeout=10).read())
    # Prefer urn:stalwart:jmap from primaryAccounts; fall back to any account.
    pa = s.get("primaryAccounts", {})
    return pa.get("urn:stalwart:jmap") or pa.get("urn:ietf:params:jmap:mail") \
        or next(iter(s.get("accounts", {})), None)

acct = discover_admin_account()
if not acct:
    print("  [FAIL] could not discover admin accountId")
    sys.exit(0)

# List existing routes by name.
r = jmap([["MtaRoute/get", {"accountId": acct, "ids": None}, "0"]])
mr = r.get("methodResponses") or []
existing = (mr[0][1].get("list") if mr else []) or []
by_name = {x.get("name"): x.get("id") for x in existing if x.get("name")}

default_route_name = None
for route in routes:
    name = route["name"]
    user = read_secret(route.get("auth_username_env"))
    pw   = read_secret(route.get("auth_secret_env"))
    payload = {
        "@type": "Relay",
        "address": route["address"],
        "port": int(route["port"]),
        "name": name,
        "protocol": route.get("protocol", "smtp"),
        "implicitTls": bool(route.get("implicit_tls", False)),
        "allowInvalidCerts": bool(route.get("allow_invalid_certs", False)),
    }
    if route.get("description"): payload["description"] = route["description"]
    if user: payload["authUsername"] = user
    if pw:   payload["authSecret"] = {"@type": "Value", "secret": pw}

    if name in by_name:
        rid = by_name[name]
        rr = jmap([["MtaRoute/set", {"accountId": acct, "update": {rid: payload}}, "0"]])
        u = (rr.get("methodResponses") or [[None,{}]])[0][1]
        if u.get("updated"):
            print(f"  updated route '{name}' (id={rid})")
        else:
            print(f"  FAIL update '{name}': {u.get('notUpdated') or rr}")
    else:
        rr = jmap([["MtaRoute/set", {"accountId": acct, "create": {"new": payload}}, "0"]])
        c = (rr.get("methodResponses") or [[None,{}]])[0][1]
        if c.get("created"):
            print(f"  created route '{name}'")
        else:
            print(f"  FAIL create '{name}': {c.get('notCreated') or rr}")

    if route.get("default_outbound"):
        default_route_name = name

# Wire MtaOutboundStrategy.route.else → '<default-route-name>' (singleton).
if default_route_name:
    strat_route = {"match": [], "else": "'" + default_route_name + "'"}
    # Try singleton-upsert via create first.
    rr = jmap([["MtaOutboundStrategy/set", {"accountId": acct,
        "create": {"new": {"route": strat_route}}}, "0"]])
    s = (rr.get("methodResponses") or [[None,{}]])[0][1]
    if s.get("created"):
        print(f"  MtaOutboundStrategy.route.else = '{default_route_name}'")
    else:
        # Singleton already exists — update by id.
        rr = jmap([["MtaOutboundStrategy/get", {"accountId": acct, "ids": None}, "0"]])
        items = ((rr.get("methodResponses") or [[None,{}]])[0][1].get("list") or [])
        if items:
            sid = items[0]["id"]
            rr = jmap([["MtaOutboundStrategy/set", {"accountId": acct,
                "update": {sid: {"route": strat_route}}}, "0"]])
            u = (rr.get("methodResponses") or [[None,{}]])[0][1]
            if u.get("updated"):
                print(f"  updated MtaOutboundStrategy → '{default_route_name}'")
            else:
                print(f"  FAIL update strategy: {u.get('notUpdated') or rr}")
        else:
            print(f"  FAIL: strategy not created and not found")
PYEOF
fi

echo "[activate] Done — folders + sieve + mta routes ensured"
